// A >=10-point swing either direction is this pass's own judgment call for 'meaningful,' not
// brief-specified - big enough to not be noise, small enough to still catch a real regression
// or improvement worth a human's attention.
const SIGNIFICANT_DELTA = 10;

const previousScore = $('Fetch Location').item.json.frontDoorAuditScore ?? null;
const newScore = $json.score;
const delta = previousScore === null ? null : newScore - previousScore;
const significant = delta !== null && Math.abs(delta) >= SIGNIFICANT_DELTA;

return [{
  json: {
    locationId: $('Fetch Location').item.json.id,
    locationName: $('Fetch Location').item.json.name,
    newScore,
    reportUrl: $json.reportUrl,
    previousScore,
    delta,
    significant,
  },
}];
